 Qb("ch06_transactions.adoc", "The modern unit of measurement", "for Bitcoin is called _weight_", "four units of weight equal one vbyte"),
 Qb("ch06_transactions.adoc", "Blocks are limited to 4 million weight.", "The block header takes up 240", "weight.", "uses either 4 or", "12 weight."),
 Qb("ch06_transactions.adoc", "chosen to", "reduce the weight used when spending a UTXO"),
 Qb("ch06_transactions.adoc", "2 | jq .weight", "569"),
 Qe("bip-0141.mediawiki", "''Transaction weight'' is defined as ''Base transaction size'' * 3 + ''Total transaction size''", "''Virtual transaction size'' is defined as ''Transaction weight'' / 4 (rounded up to the next integer).", "The new rule is ''block weight'' ≤ 4,000,000."),
 Qc("src/consensus/consensus.h", "MAX_BLOCK_WEIGHT{4'000'000}", "WITNESS_SCALE_FACTOR = 4"),
 Qc("src/consensus/validation.h", "return ::GetSerializeSize(TX_NO_WITNESS(tx)) * (WITNESS_SCALE_FACTOR - 1) + ::GetSerializeSize(TX_WITH_WITNESS(tx));"),
 # the weight, recomputed and compared with the book's figure and the explorer's
