 X("C.ev_json('mempool_tx_466200308696215b_v1_0_0.json')['weight']", 569),
 X("sum(w for n, b, f, w in T.field_weights(%r))" % ALICE, 569),
 X("[(n, b, f, w) for n, b, f, w in T.field_weights(%r) if f == 1]" % ALICE, [('marker', 1, 1, 1), ('flag', 1, 1, 1), ('witness 0 count', 1, 1, 1), ('witness 0 item 0 length', 1, 1, 1), ('witness 0 item 0', 65, 1, 65)]),
